-- =====================================================================
-- Начальное наполнение каталога курсов. Всё редактируется в админ-панели.
-- Уроки создаются скрытыми; видео к ним прикрепляется загрузкой в админке
-- (или импортом), после чего урок публикуется.
-- Идентификаторы фиксированы, чтобы файл можно было безопасно применить повторно.
-- =====================================================================

insert into app.course_categories (id, slug, title, description, sort) values
  ('6a1f0c0e-1b2a-4c3d-8e4f-000000000001', 'nizhnie-konechnosti', 'Нижние конечности',
   'Комплексы упражнений для поддержания подвижности, укрепления мышц и профилактики мышечного напряжения в области стоп, голеностопных, коленных и тазобедренных суставов.', 1),
  ('6a1f0c0e-1b2a-4c3d-8e4f-000000000002', 'spina-i-korpus', 'Спина и корпус',
   'Комплексы упражнений для здоровья спины: подвижность позвоночника, укрепление мышц корпуса, профилактика напряжения в пояснице и грудном отделе.', 2),
  ('6a1f0c0e-1b2a-4c3d-8e4f-000000000003', 'sheya-plechi-golova', 'Шея, плечевой пояс и голова',
   'Упражнения для подвижности шейного отдела и мышц шейно-воротниковой зоны, уменьшения мышечного напряжения и профилактики дискомфорта при долгом статичном положении.', 3),
  ('6a1f0c0e-1b2a-4c3d-8e4f-000000000004', 'verhnie-konechnosti', 'Верхние конечности',
   'Упражнения для локтевых, лучезапястных суставов и кистей: подвижность, укрепление мышц предплечья, профилактика перегрузки при однообразной работе руками.', 4)
on conflict (id) do nothing;

-- Общие тексты
create temporary table _t on commit drop as select
  E'Упражнения подходят не всем. Перед началом занятий проконсультируйтесь с врачом, особенно если у вас есть хронические заболевания суставов или позвоночника.\n\nНе выполняйте упражнения и обратитесь к специалисту, если:\n- сустав горячий на ощупь, отёчный или покрасневший;\n- боль появилась недавно, резко или после травмы;\n- в последние месяцы была операция на этом суставе — заниматься можно только с разрешения лечащего врача;\n- повышена температура тела, есть острое инфекционное заболевание или обострение хронического;\n- артериальное давление высокое или нестабильное;\n- вы беременны — сначала согласуйте нагрузку с врачом.\n\nВо время занятия:\n- двигайтесь плавно, без рывков и через «не могу»;\n- если упражнение вызывает боль (а не обычное мышечное усилие) — остановитесь;\n- если после занятий боль усиливается или держится дольше суток — прекратите и запишитесь на консультацию.\n\nКурс носит профилактический и ознакомительный характер. Он не является медицинской услугой и не заменяет осмотр, диагностику и лечение у врача.'::text as contra,
  E'Доступ открывается автоматически после подтверждения оплаты и действует без ограничения срока, пока курс размещён на сайте.\nСмотреть уроки можно с телефона, планшета или компьютера после входа в личный кабинет. Одновременно — на одном устройстве.\nДоступ персональный: передавать его другим людям и копировать видео запрещено.'::text as terms,
  E'- Занимайтесь 3–4 раза в неделю, лучше в одно и то же время.\n- Перед занятием сделайте лёгкую разминку: пройдитесь, покрутите стопами и плечами 2–3 минуты.\n- Повторяйте за специалистом в видео в спокойном темпе. Количество повторений можно уменьшить, если устаёте.\n- Отмечайте самочувствие. Если упражнение даётся тяжело или вызывает дискомфорт — вернитесь к предыдущему уроку или сделайте перерыв.'::text as recs;

insert into app.courses (id, slug, category_id, title, short, direction, for_whom, tasks, program, results, recommendations,
  contraindications, access_terms, price, old_price, sort)
select * from (values
  ('7b2e1d0f-2c3b-4d4e-9f50-000000000001'::uuid, 'kolennye-sustavy', '6a1f0c0e-1b2a-4c3d-8e4f-000000000001'::uuid,
   'Здоровые колени',
   'Два коротких комплекса упражнений для коленных суставов: укрепление мышц бедра и голени и поддержание подвижности колена.',
   'Коленные суставы',
   E'- тем, кто чувствует скованность или дискомфорт в коленях после нагрузки или долгого сидения;\n- тем, кто много ходит, стоит или занимается спортом и хочет снизить нагрузку на колени;\n- тем, кто после консультации врача хочет заниматься дома регулярно и по понятной программе.',
   E'- поддерживать подвижность коленного сустава;\n- укреплять мышцы бедра и голени, которые стабилизируют колено;\n- снижать мышечное напряжение вокруг сустава;\n- выработать привычку к короткой регулярной зарядке для ног.',
   E'Два видеоурока по 1–2 минуты. В каждом специалист клиники показывает упражнения и объясняет, как их выполнять правильно и на что обращать внимание.',
   E'При регулярных занятиях можно ожидать, что мышцы вокруг колена станут крепче, а движения — свободнее. Результат индивидуален и зависит от состояния суставов, регулярности и соблюдения техники.',
   (select recs from _t), (select contra from _t), (select terms from _t), 1490::numeric, null::numeric, 1),
  ('7b2e1d0f-2c3b-4d4e-9f50-000000000002', 'tazobedrennye-sustavy', '6a1f0c0e-1b2a-4c3d-8e4f-000000000001',
   'Тазобедренные суставы',
   'Упражнения стоя и лёжа для мышц, окружающих тазобедренный сустав: подвижность, стабильность и мягкое укрепление.',
   'Тазобедренные суставы',
   E'- тем, кто ощущает скованность в области таза и бедра по утрам или после долгого сидения;\n- тем, у кого сидячая работа и мало движения в течение дня;\n- тем, кто хочет укрепить ягодичные мышцы и мышцы бедра без тренажёров.',
   E'- поддерживать подвижность тазобедренного сустава;\n- укреплять ягодичные мышцы и мышцы бедра;\n- улучшать устойчивость при ходьбе;\n- снижать напряжение мышц после долгого сидения.',
   E'Два видеоурока: комплекс стоя и комплекс лёжа на коврике. Упражнения можно выполнять дома, нужен только коврик и устойчивая опора рядом.',
   E'При регулярных занятиях можно ожидать большей свободы движений в тазобедренном суставе и более уверенной опоры при ходьбе. Результат индивидуален.',
   (select recs from _t), (select contra from _t), (select terms from _t), 1490, null, 2),
  ('7b2e1d0f-2c3b-4d4e-9f50-000000000003', 'loktevoy-sustav', '6a1f0c0e-1b2a-4c3d-8e4f-000000000004',
   'Локтевой сустав',
   'Комплекс упражнений для локтя и мышц предплечья — для тех, у кого руки много работают однообразно.',
   'Локтевой сустав',
   E'- тем, чья работа или хобби связаны с однообразными движениями рук: компьютер, инструменты, ракеточные виды спорта;\n- тем, кто замечает усталость и напряжение в предплечье к концу дня;\n- тем, кто после консультации врача хочет поддерживать руки в тонусе дома.',
   E'- укреплять мышцы предплечья и плеча, которые работают вместе с локтем;\n- поддерживать подвижность локтевого сустава;\n- снижать напряжение мышц после однообразной нагрузки.',
   E'Видеоурок с комплексом упражнений: специалист показывает технику, количество подходов и типичные ошибки. Для части упражнений понадобится небольшая гантель или бутылка с водой.',
   E'При регулярных занятиях можно ожидать, что мышцы предплечья станут выносливее, а руки будут меньше уставать от повседневной нагрузки. Результат индивидуален.',
   (select recs from _t), (select contra from _t), (select terms from _t), 1490, null, 3)
) v (id, slug, category_id, title, short, direction, for_whom, tasks, program, results, recommendations, contraindications, access_terms, price, old_price, sort)
on conflict (id) do nothing;

